import { createContext } from 'react'

/** A range registers only its first input with the enclosing single-control Field. */
export const TimeFieldRegistrationContext = createContext(true)

/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-time-picker,
:where([data-moru-registry]) .ui-time-picker-popup {
  --ui-time-height: var(--ui-control-height-md, 40px);
  --ui-time-padding: var(--ui-control-padding-x-md, 14px);
  --ui-time-icon: var(--ui-icon-size-md, 16px);
  --ui-time-border: var(--ui-border-width, 1px);
  --ui-time-resolved-height: max(
    var(--ui-time-height),
    calc(
      max(
          var(--ui-type-label-size, 13px) * var(--ui-type-label-line-height, 1.5),
          var(--ui-time-icon)
        ) +
        var(--ui-space, 4px) * 2 + var(--ui-time-border) * 2
    )
  );
  --ui-time-inner-height: calc(var(--ui-time-resolved-height) - var(--ui-time-border) * 2);
  box-sizing: border-box;
  display: grid;
  gap: var(--ui-field-gap, 8px);
  min-width: 0;
  width: 100%;
  color: var(--ui-text, #171717);
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-label-size, 13px);
  line-height: var(--ui-type-label-line-height, 1.5);
  letter-spacing: var(--ui-type-label-letter-spacing, 0em);
}
:where([data-moru-registry]) .ui-time-picker[data-size='sm'],
:where([data-moru-registry]) .ui-time-picker-popup[data-size='sm'] {
  --ui-time-height: var(--ui-control-height-sm, 32px);
  --ui-time-padding: var(--ui-control-padding-x-sm, 10px);
  --ui-time-icon: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-time-picker[data-size='lg'],
:where([data-moru-registry]) .ui-time-picker-popup[data-size='lg'] {
  --ui-time-height: var(--ui-control-height-lg, 48px);
  --ui-time-padding: var(--ui-control-padding-x-lg, 18px);
  --ui-time-icon: var(--ui-icon-size-lg, 20px);
}
:where([data-moru-registry]) .ui-time-picker-label {
  font-weight: var(--ui-type-label-weight, 500);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-time-picker-control {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  min-width: 0;
  width: 100%;
  min-height: var(--ui-time-resolved-height);
  border: var(--ui-time-border) solid var(--ui-control-border, var(--ui-border, #8a8a86));
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-input-bg, #f0f0ed);
}
:where([data-moru-registry]) .ui-time-picker-control:where(:not(:focus-within)):hover:not(
    :has(input:is(:disabled, [aria-busy='true']), input[aria-invalid='true'])
  ) {
  border-color: var(--ui-control-hover-border);
  background-color: var(--ui-control-hover-bg);
}

:where([data-moru-registry]) .ui-time-picker-control:has([aria-invalid='true']) {
  border-color: var(--ui-danger, #b93d37);
  background: var(--ui-danger-soft, #f9efef);
  box-shadow: 0 0 0 1px var(--ui-error-ring, var(--ui-danger, #b93d37));
  outline-color: var(--ui-error-ring, var(--ui-danger, #b93d37));
}
:where([data-moru-registry]) .ui-time-picker-control:has(input:is(:disabled, [aria-busy='true'])) {
  background: var(--ui-disabled-bg);
  color: var(--ui-disabled-text);
  box-shadow: none;
}
:where([data-moru-registry]) .ui-time-picker-input {
  box-sizing: border-box;
  flex: 1 1 0;
  width: 0;
  min-width: 0;
  min-height: var(--ui-time-inner-height);
  padding: var(--ui-space, 4px) var(--ui-time-padding);
  border: 0;
  border-radius: inherit;
  outline: none;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: var(--ui-type-body-weight, 400);
  font-variant-numeric: tabular-nums;
}
:where([data-moru-registry]) .ui-time-picker-input::-webkit-calendar-picker-indicator {
  display: none;
}
:where([data-moru-registry]) .ui-time-picker-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--ui-time-inner-height);
  min-height: var(--ui-time-inner-height);
  padding: var(--ui-space, 4px);
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: var(--ui-muted);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-time-picker-action > svg {
  flex: none;
  width: var(--ui-time-icon);
  height: var(--ui-time-icon);
}
:where([data-moru-registry]) .ui-time-picker-action:hover:not(:disabled) {
  background: var(--ui-control-hover-bg);
  color: var(--ui-text);
}
:where([data-moru-registry]) .ui-time-picker-action:disabled {
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-time-picker-action:focus-visible,
:where([data-moru-registry]) .ui-time-picker-grid button:focus-visible,
:where([data-moru-registry]) .ui-time-picker-panel footer button:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: -2px;
}
:where([data-moru-registry]) .ui-time-picker-error {
  margin: 0;
  color: var(--ui-danger-surface-text, var(--ui-danger));
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  letter-spacing: var(--ui-type-caption-letter-spacing, 0em);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-time-picker-popup {
  width: min(320px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  padding: var(--ui-control-gap, 8px);
}
:where([data-moru-registry]) .ui-time-picker-panel {
  outline: none;
  min-width: 0;
}
:where([data-moru-registry]) .ui-time-picker-panel > header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ui-control-gap, 8px);
  padding: var(--ui-control-gap, 8px) var(--ui-control-gap, 8px)
    calc(var(--ui-control-gap, 8px) * 2);
  flex-wrap: wrap;
  border-bottom: var(--ui-border-width, 1px) solid var(--ui-border);
}
:where([data-moru-registry]) .ui-time-picker-panel > header strong {
  font-size: var(--ui-type-label-size, 13px);
  font-weight: var(--ui-type-label-weight, 600);
  line-height: var(--ui-type-label-line-height, 1.5);
}
:where([data-moru-registry]) .ui-time-picker-panel > header span {
  font-family: var(--ui-font-family-code, monospace);
  font-size: calc(var(--ui-type-label-size, 13px) + var(--ui-space, 4px));
  line-height: var(--ui-type-label-line-height, 1.5);
  font-weight: var(--ui-type-label-weight, 500);
}
:where([data-moru-registry]) .ui-time-picker-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: calc(var(--ui-control-gap, 8px) * 1.5);
  padding: calc(var(--ui-control-gap, 8px) * 1.5) var(--ui-space, 4px);
  min-width: 0;
}
:where([data-moru-registry]) .ui-time-picker-columns > section {
  min-width: 0;
}
:where([data-moru-registry]) .ui-time-picker-columns h4 {
  margin: 0 0 var(--ui-control-gap, 8px);
  color: var(--ui-muted);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 500);
  line-height: var(--ui-type-caption-line-height, 1.5);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-time-picker-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-content: start;
  gap: var(--ui-space, 4px);
  max-height: calc(var(--ui-time-resolved-height) * 6 + var(--ui-space, 4px) * 5);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}
:where([data-moru-registry]) .ui-time-picker-grid button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-width: 0;
  min-height: var(--ui-time-resolved-height);
  padding: var(--ui-space, 4px) calc(var(--ui-space, 4px) / 2);
  border: var(--ui-border-width, 1px) solid transparent;
  border-radius: max(3px, calc(var(--ui-radius, 6px) * 0.65));
  background: transparent;
  color: var(--ui-text);
  font: inherit;
  font-size: var(--ui-type-caption-size, 12px);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
:where([data-moru-registry]) .ui-time-picker-grid button:hover:not(:disabled) {
  background: var(--ui-control-hover-bg);
}
:where([data-moru-registry]) .ui-time-picker-grid button[aria-pressed='true'] {
  background: var(--ui-primary);
  color: var(--ui-primary-foreground);
}
:where([data-moru-registry]) .ui-time-picker-grid button:disabled {
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-time-picker-grid > p {
  grid-column: 1/-1;
  margin: 0;
  font-size: var(--ui-type-caption-size, 12px);
  line-height: 1.6;
  color: var(--ui-muted);
}
:where([data-moru-registry]) .ui-time-picker-panel > footer {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--ui-control-gap, 8px);
  padding: calc(var(--ui-control-gap, 8px) * 1.5) var(--ui-space, 4px) var(--ui-space, 4px);
  border-top: var(--ui-border-width, 1px) solid var(--ui-border);
}
:where([data-moru-registry]) .ui-time-picker-panel footer button {
  box-sizing: border-box;
  min-height: var(--ui-time-resolved-height);
  padding: var(--ui-space, 4px) var(--ui-time-padding);
  border: 0;
  border-radius: var(--ui-radius, 6px);
  background: transparent;
  color: var(--ui-text);
  font: inherit;
  font-size: var(--ui-type-label-size, 13px);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-time-picker-panel footer .ui-time-picker-apply {
  background: var(--ui-primary);
  color: var(--ui-primary-foreground);
}
:where([data-moru-registry]) .ui-time-picker-panel footer button:disabled {
  background: var(--ui-disabled-bg);
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}
@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-time-picker,
  :where([data-moru-registry]) .ui-time-picker-popup {
    --ui-time-resolved-height: max(
      44px,
      var(--ui-time-height),
      calc(
        max(
            max(16px, var(--ui-type-label-size, 13px)) * var(--ui-type-label-line-height, 1.5),
            var(--ui-time-icon)
          ) +
          var(--ui-space, 4px) * 2 + var(--ui-time-border) * 2
      )
    );
  }
  :where([data-moru-registry]) .ui-time-picker-input {
    font-size: max(16px, var(--ui-type-label-size, 13px));
  }
  :where([data-moru-registry]) .ui-time-picker-action {
    width: max(44px, var(--ui-time-inner-height));
  }
  :where([data-moru-registry]) .ui-time-picker-grid {
    grid-template-columns: repeat(auto-fit, minmax(44px, 1fr));
  }
}
@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-time-picker,
  :where([data-moru-registry]) .ui-time-picker-popup {
    --ui-time-border: 1px;
  }
  :where([data-moru-registry]) .ui-time-picker-control {
    border: var(--ui-time-border) solid ButtonText;
  }
  :where([data-moru-registry]) .ui-time-picker-grid button[aria-pressed='true'],
  :where([data-moru-registry]) .ui-time-picker-apply {
    border: 2px solid Highlight;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import {
  forwardRef,
  useContext,
  useEffect,
  useId,
  useImperativeHandle,
  useRef,
  useState,
  type InputHTMLAttributes,
  type KeyboardEvent,
} from 'react'
import { Input as BaseInput } from '@base-ui/react/input'
import { Popover as BasePopover } from '@base-ui/react/popover'
import { Clock3, X } from 'lucide-react'
import { cn } from './_lib/cn'
import { mergeDescriptionIds, useFieldContext } from './field-context'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import { TimeFieldRegistrationContext } from './time-field-context'
import {
  formatTime,
  getAvailableMinutes,
  getTimeValidationError,
  normalizeTime,
  normalizeTimeStep,
  parseTime,
  subscribeTimeFormReset,
  wrapTimeOptionIndex,
} from './time-utils'
import './popover.css'
import './time-shared.css'
import './time-picker.css'

export interface TimePickerProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'type' | 'value' | 'defaultValue' | 'size' | 'step' | 'min' | 'max'
> {
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  label?: string
  min?: string
  max?: string
  /** Interval in minutes, from 1 to 60. The step base is min, or midnight. */
  step?: number
  size?: 'sm' | 'md' | 'lg'
  clearable?: boolean
  error?: string
  loading?: boolean
}

const pad = (value: number) => String(value).padStart(2, '0')

export const TimePicker = forwardRef<HTMLInputElement, TimePickerProps>(function TimePicker(
  {
    value,
    defaultValue = null,
    onValueChange,
    label,
    min,
    max,
    step = 1,
    size = 'md',
    clearable = true,
    error,
    className,
    id,
    form,
    disabled,
    readOnly,
    required,
    loading = false,
    onChange,
    onBlur,
    onInvalid,
    onKeyDown,
    'aria-label': ariaLabel,
    'aria-labelledby': labelledBy,
    'aria-describedby': describedBy,
    'aria-invalid': invalid,
    ...props
  },
  forwardedRef,
) {
  const { t } = useI18n()

  const generatedId = useId()
  const field = useFieldContext()
  const registerWithField = useContext(TimeFieldRegistrationContext)
  const portal = useThemePortalContainer()
  const unavailable = disabled || loading
  const inputRef = useRef<HTMLInputElement>(null)
  const panelRef = useRef<HTMLDivElement>(null)
  const [internal, setInternal] = useState<string | null>(() => normalizeTime(defaultValue))
  const [open, setOpen] = useState(false)
  const [validation, setValidation] = useState<string | null>(null)
  const selected = normalizeTime(value === undefined ? internal : value)
  const constraints = {
    min: normalizeTime(min) ?? undefined,
    max: normalizeTime(max) ?? undefined,
    step: normalizeTimeStep(step),
  }
  const availableHours = Array.from({ length: 24 }, (_, hour) => hour).filter(
    (hour) => getAvailableMinutes(hour, constraints).length > 0,
  )
  const initialMinutes = parseTime(selected)
  const [draftHour, setDraftHour] = useState(() =>
    initialMinutes === null ? (availableHours[0] ?? 0) : Math.floor(initialMinutes / 60),
  )
  const [draftMinute, setDraftMinute] = useState(() =>
    initialMinutes === null
      ? (getAvailableMinutes(draftHour, constraints)[0] ?? 0)
      : initialMinutes % 60,
  )
  const availableMinutes = getAvailableMinutes(draftHour, constraints)
  const controlId =
    id ?? (registerWithField ? field?.controlId : undefined) ?? `${generatedId}-input`
  const pickerLabel = label ?? ariaLabel ?? t('시간')
  const labelId = `${generatedId}-label`
  const inputLabelledBy =
    labelledBy ??
    (ariaLabel ? undefined : mergeDescriptionIds(field?.labelId, label ? labelId : undefined))
  const message = error || validation
  const computedError =
    !unavailable && !readOnly ? error || getTimeValidationError(selected, constraints, t) || '' : ''
  const resetState = useRef({ value, defaultValue, selected })
  resetState.current = { value, defaultValue, selected }
  useImperativeHandle(forwardedRef, () => inputRef.current!, [])

  useEffect(() => {
    inputRef.current?.setCustomValidity(computedError)
  }, [computedError, selected])
  useEffect(() => {
    const owner = inputRef.current?.form
    if (!owner) return
    return subscribeTimeFormReset(owner, () => {
      const next =
        resetState.current.value === undefined
          ? normalizeTime(resetState.current.defaultValue)
          : resetState.current.selected
      if (resetState.current.value === undefined) setInternal(next)
      if (inputRef.current) inputRef.current.value = next ?? ''
      setValidation(null)
      setOpen(false)
    })
  }, [form])
  useEffect(() => {
    if (unavailable || readOnly) setOpen(false)
  }, [unavailable, readOnly])
  useEffect(() => {
    setValidation(null)
  }, [selected, min, max, step, unavailable, readOnly])
  useEffect(() => {
    setOpen(false)
  }, [min, max, step])

  function change(next: string | null) {
    if (unavailable || readOnly) return
    if (value === undefined) setInternal(next)
    setValidation(null)
    onValueChange?.(next)
  }
  function openPicker(next: boolean) {
    if (unavailable || readOnly) return
    if (next) {
      const current = parseTime(selected)
      const hour =
        current !== null && availableHours.includes(Math.floor(current / 60))
          ? Math.floor(current / 60)
          : (availableHours[0] ?? 0)
      const minutes = getAvailableMinutes(hour, constraints)
      setDraftHour(hour)
      setDraftMinute(
        current !== null && minutes.includes(current % 60) ? current % 60 : (minutes[0] ?? 0),
      )
    }
    setOpen(next)
  }
  function gridKey(
    event: KeyboardEvent<HTMLButtonElement>,
    choices: number[],
    current: number,
    select: (value: number) => void,
  ) {
    const grid = event.currentTarget.parentElement
    const columns = grid
      ? getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length || 4
      : 4
    const offset =
      event.key === 'ArrowRight'
        ? 1
        : event.key === 'ArrowLeft'
          ? -1
          : event.key === 'ArrowDown'
            ? columns
            : event.key === 'ArrowUp'
              ? -columns
              : 0
    const index = choices.indexOf(current)
    const next =
      event.key === 'Home'
        ? choices[0]
        : event.key === 'End'
          ? choices.at(-1)
          : offset && choices.length
            ? choices[wrapTimeOptionIndex(Math.max(0, index) + offset, choices.length)]
            : undefined
    if (next === undefined) return
    event.preventDefault()
    select(next)
    event.currentTarget.parentElement
      ?.querySelector<HTMLButtonElement>(`button[data-value="${next}"]`)
      ?.focus()
  }
  function chooseHour(hour: number) {
    setDraftHour(hour)
    const options = getAvailableMinutes(hour, constraints)
    if (!options.includes(draftMinute)) setDraftMinute(options[0] ?? 0)
  }
  const inputProps = {
    ...props,
    id: controlId,
    form,
    // Busy locks the field with readOnly, not disabled: it keeps keyboard focus and
    // its value still takes part in form submission.
    disabled,
    readOnly: readOnly || loading,
    required,
    type: 'time',
    ref: inputRef,
    value: selected ?? '',
    min: constraints.min,
    max: constraints.max,
    step: constraints.step * 60,
    className: 'ui-time-picker-input',
    'aria-label': ariaLabel ?? (!field && !label ? t('시간') : undefined),
    'aria-labelledby': inputLabelledBy,
    'aria-describedby': mergeDescriptionIds(
      describedBy,
      field?.describedBy,
      message ? `${generatedId}-error` : undefined,
    ),
    'aria-invalid': message ? true : (invalid ?? (field?.invalid || undefined)),
    'aria-busy': loading || undefined,
    onChange: (event: React.ChangeEvent<HTMLInputElement>) => {
      if (!unavailable && !readOnly) {
        change(normalizeTime(event.currentTarget.value))
        onChange?.(event)
      }
    },
    onKeyDown: (event: KeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event)
      if (event.defaultPrevented || unavailable || readOnly) return
      if (event.altKey && event.key === 'ArrowDown') {
        event.preventDefault()
        openPicker(true)
      }
    },
    onBlur: (event: React.FocusEvent<HTMLInputElement>) => {
      if (
        event.currentTarget.value &&
        !event.currentTarget.validity.valid &&
        !unavailable &&
        !readOnly
      )
        setValidation(computedError || t('시간을 확인해 주세요.'))
      onBlur?.(event)
    },
    onInvalid: (event: React.InvalidEvent<HTMLInputElement>) => {
      onInvalid?.(event)
      if (event.defaultPrevented) return
      event.preventDefault()
      setValidation(
        error ||
          computedError ||
          (event.currentTarget.validity.valueMissing
            ? t('시간을 선택해 주세요.')
            : t('시간을 확인해 주세요.')),
      )
      const owner = event.currentTarget.form
      const first = owner
        ? Array.from(owner.elements).find((element) => {
            const input = element as HTMLInputElement
            return input.willValidate && input.validity && !input.validity.valid
          })
        : event.currentTarget
      if (first === event.currentTarget) inputRef.current?.focus()
    },
  }
  return (
    <div
      className={cn('ui-time-picker', className)}
      data-size={size}
      data-disabled={unavailable || undefined}
      data-loading={loading || undefined}
      aria-busy={loading || undefined}
    >
      {label ? (
        <label className="ui-time-picker-label" id={labelId} htmlFor={controlId}>
          {label}
        </label>
      ) : null}
      <BasePopover.Root open={open && !unavailable && !readOnly} onOpenChange={openPicker}>
        <div className="ui-time-picker-control ui-field-focus">
          {registerWithField ? <BaseInput {...inputProps} /> : <input {...inputProps} />}
          {clearable && selected && !readOnly ? (
            <button
              type="button"
              className="ui-time-picker-action"
              aria-label={t('{v0} 지우기', { v0: pickerLabel })}
              disabled={unavailable}
              onClick={() => {
                change(null)
                inputRef.current?.focus()
              }}
            >
              <X size={14} aria-hidden="true" />
            </button>
          ) : null}
          <BasePopover.Trigger
            className="ui-time-picker-action"
            aria-label={t('{v0} 선택 열기', { v0: pickerLabel })}
            disabled={unavailable || readOnly}
          >
            {loading ? (
              <span className="ui-loading-indicator" aria-hidden="true" />
            ) : (
              <Clock3 size={16} aria-hidden="true" />
            )}
          </BasePopover.Trigger>
        </div>
        <OverlayPortal portal={BasePopover.Portal} kind="popover" container={portal}>
          <BasePopover.Positioner
